    'How do I accept a load?': '\u{643}\u{64a}\u{641} \u{623}\u{642}\u{628}\u{644} \u{62d}\u{645}\u{648}\u{644}\u{629}\u{61f}',
    'The assistant returned an empty response.': '\u{623}\u{631}\u{62c}\u{639} \u{627}\u{644}\u{645}\u{633}\u{627}\u{639}\u{62f} \u{631}\u{62f}\u{627}\u{64b} \u{641}\u{627}\u{631}\u{63a}\u{627}\u{64b}.',
    'I couldn’t reach the assistant. Please check your connection and try again.': '\u{62a}\u{639}\u{630}\u{631} \u{627}\u{644}\u{648}\u{635}\u{648}\u{644} \u{625}\u{644}\u{649} \u{627}\u{644}\u{645}\u{633}\u{627}\u{639}\u{62f}. \u{62a}\u{62d}\u{642}\u{642} \u{645}\u{646} \u{627}\u{62a}\u{635}\u{627}\u{644}\u{643} \u{648}\u{62d}\u{627}\u{648}\u{644} \u{645}\u{631}\u{629} \u{623}\u{62e}\u{631}\u{649}.',
    'The assistant service was not found (HTTP 404). Deploy the assistant-chat Supabase function and try again.': '\u{644}\u{645} \u{64a}\u{62a}\u{645} \u{627}\u{644}\u{639}\u{62b}\u{648}\u{631} \u{639}\u{644}\u{649} \u{62e}\u{62f}\u{645}\u{629} \u{627}\u{644}\u{645}\u{633}\u{627}\u{639}\u{62f} (HTTP 404). \u{627}\u{646}\u{634}\u{631} \u{62f}\u{627}\u{644}\u{629} assistant-chat \u{641}\u{64a} Supabase \u{648}\u{62d}\u{627}\u{648}\u{644} \u{645}\u{631}\u{629} \u{623}\u{62e}\u{631}\u{649}.',
    'This permanently deletes the conversation and all its messages.': '\u{633}\u{64a}\u{624}\u{62f}\u{64a} \u{647}\u{630}\u{627} \u{625}\u{644}\u{649} \u{62d}\u{630}\u{641} \u{627}\u{644}\u{645}\u{62d}\u{627}\u{62f}\u{62b}\u{629} \u{648}\u{62c}\u{645}\u{64a}\u{639} \u{631}\u{633}\u{627}\u{626}\u{644}\u{647}\u{627} \u{646}\u{647}\u{627}\u{626}\u{64a}\u{627}\u{64b}.',
    'Could not delete this support chat.': '\u{62a}\u{639}\u{630}\u{631} \u{62d}\u{630}\u{641} \u{645}\u{62d}\u{627}\u{62f}\u{62b}\u{629} \u{627}\u{644}\u{62f}\u{639}\u{645} \u{647}\u{630}\u{647}.',
    'Could not start guest chat. Please try again.': '\u{62a}\u{639}\u{630}\u{631} \u{628}\u{62f}\u{621} \u{645}\u{62d}\u{627}\u{62f}\u{62b}\u{629} \u{627}\u{644}\u{636}\u{64a}\u{641}. \u{64a}\u{631}\u{62c}\u{649} \u{627}\u{644}\u{645}\u{62d}\u{627}\u{648}\u{644}\u{629} \u{645}\u{631}\u{629} \u{623}\u{62e}\u{631}\u{649}.',
    'Guest chat could not start. Check anonymous sign-in settings and the Supabase database logs.': '\u{62a}\u{639}\u{630}\u{631} \u{628}\u{62f}\u{621} \u{645}\u{62d}\u{627}\u{62f}\u{62b}\u{629} \u{627}\u{644}\u{636}\u{64a}\u{641}. \u{62a}\u{62d}\u{642}\u{642} \u{645}\u{646} \u{625}\u{639}\u{62f}\u{627}\u{62f}\u{627}\u{62a} \u{62a}\u{633}\u{62c}\u{64a}\u{644} \u{627}\u{644}\u{62f}\u{62e}\u{648}\u{644} \u{627}\u{644}\u{645}\u{62c}\u{647}\u{648}\u{644} \u{648}\u{633}\u{62c}\u{644}\u{627}\u{62a} \u{642}\u{627}\u{639}\u{62f}\u{629} \u{628}\u{64a}\u{627}\u{646}\u{627}\u{62a} Supabase.',
    'Support chat is unavailable. Apply the live support database migration and try again.': '\u{645}\u{62d}\u{627}\u{62f}\u{62b}\u{629} \u{627}\u{644}\u{62f}\u{639}\u{645} \u{63a}\u{64a}\u{631} \u{645}\u{62a}\u{627}\u{62d}\u{629}. \u{637}\u{628}\u{651}\u{642} \u{62a}\u{631}\u{62d}\u{64a}\u{644} \u{642}\u{627}\u{639}\u{62f}\u{629} \u{628}\u{64a}\u{627}\u{646}\u{627}\u{62a} \u{627}\u{644}\u{62f}\u{639}\u{645} \u{627}\u{644}\u{645}\u{628}\u{627}\u{634}\u{631} \u{648}\u{62d}\u{627}\u{648}\u{644} \u{645}\u{631}\u{629} \u{623}\u{62e}\u{631}\u{649}.',
    'Support request · ': '\u{637}\u{644}\u{628} \u{62f}\u{639}\u{645} \u{b7} ',
    'Phone number already registered': '\u{631}\u{642}\u{645} \u{627}\u{644}\u{647}\u{627}\u{62a}\u{641} \u{645}\u{633}\u{62c}\u{651}\u{644} \u{645}\u{633}\u{628}\u{642}\u{627}\u{64b}',
    'This phone number already has an account. Please log in instead, or use a different phone number.': '\u{64a}\u{648}\u{62c}\u{62f} \u{62d}\u{633}\u{627}\u{628} \u{645}\u{631}\u{62a}\u{628}\u{637} \u{628}\u{631}\u{642}\u{645} \u{627}\u{644}\u{647}\u{627}\u{62a}\u{641} \u{647}\u{630}\u{627}. \u{64a}\u{631}\u{62c}\u{649} \u{62a}\u{633}\u{62c}\u{64a}\u{644} \u{627}\u{644}\u{62f}\u{62e}\u{648}\u{644}\u{60c} \u{623}\u{648} \u{627}\u{633}\u{62a}\u{62e}\u{62f}\u{627}\u{645} \u{631}\u{642}\u{645} \u{647}\u{627}\u{62a}\u{641} \u{622}\u{62e}\u{631}.',
    'Use another number': '\u{627}\u{633}\u{62a}\u{62e}\u{62f}\u{627}\u{645} \u{631}\u{642}\u{645} \u{622}\u{62e}\u{631}',
    'Go to Login': '\u{627}\u{644}\u{630}\u{647}\u{627}\u{628} \u{625}\u{644}\u{649} \u{62a}\u{633}\u{62c}\u{64a}\u{644} \u{627}\u{644}\u{62f}\u{62e}\u{648}\u{644}',
  };
  return arabic[english] ?? english;
}

class LanguageToggleButton extends StatelessWidget {
  const LanguageToggleButton({super.key});

  @override
  Widget build(BuildContext context) => IconButton(
    tooltip: AppLanguageController.instance.isArabic
        ? 'Switch to English'
        : '\u{0627}\u{0644}\u{062a}\u{0628}\u{062f}\u{064a}\u{0644} \u{0625}\u{0644}\u{0649} \u{0627}\u{0644}\u{0639}\u{0631}\u{0628}\u{064a}\u{0629}',
    onPressed: AppLanguageController.instance.toggle,
    icon: Text(
      AppLanguageController.instance.isArabic ? 'EN' : '\u{0639}',
      style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 18),
    ),
  );
}

